{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Mulberroside A, a glycoside, undergoes rapid deglycosylation in human intestinal bacteria and has low oral bioavailability; this supports low parent bioavailability for staphyloxanthin, which also contains a glycosidic sugar moiety.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Lycopene, a structurally related carotenoid, showed only ~2.6% systemic availability after oral capsule dosing in humans, supporting low oral bioavailability for a large lipophilic carotenoid-like molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Phytoene, a more saturated C40 carotenoid, was estimated at 58.5% absolute bioavailability in humans; this is contradictory to a low prediction but has limited transferability because staphyloxanthin is a larger glycosylated fatty-acid ester rather than a hydrocarbon carotenoid.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "In one human study, all-trans lycopene bioavailability was 23.2%, above the 20% threshold; this is contradictory to a low prediction but is offset by multiple lower lycopene estimates and is not directly applicable to staphyloxanthin.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low because staphyloxanthin is a large, extremely lipophilic glycosylated carotenoid ester; the most transferable experimental evidence (lycopene low systemic availability, mulberroside A glycoside low bioavailability) supports F < 20%, while the high phytoene/lycopene estimates are less transferable due to structural differences.",
  "evidence_gaps": [
    "No direct oral bioavailability data for staphyloxanthin.",
    "No experimental data on intestinal stability or hydrolysis of staphyloxanthin's glycosidic or ester bonds.",
    "Carotenoid bioavailability is highly dependent on formulation and food matrix; no formulation data for staphyloxanthin.",
    "No data on lymphatic absorption or first-pass metabolism for staphyloxanthin."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

